import{_ as a,a as t,c as n,ac as d}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"Codex 插件用途与选择记录","description":"插件在工作流、文档检索、PR 和记忆中的用途","frontmatter":{"title":"Codex 插件用途与选择记录","description":"插件在工作流、文档检索、PR 和记忆中的用途","sources":[{"repository":"TeamDocs","file":"docs/engineering/codex/Plugin.md"}],"showdocs":{"topics":[{"id":"ai","title":"AI 与 Codex","link":"/topics/ai/"},{"id":"engineering","title":"编辑器与 IDE","link":"/topics/engineering/"}],"kind":"AI与Codex任务与配置","scope":"historical","audience":"general","group":"工程与工具","summary":"插件在工作流、文档检索、PR 和记忆中的用途","status":"active","related":[{"title":"全局 AGENTS.md","link":"/tools/ai/guide/global-agents","kind":"AI与Codex上手与对象","scope":"general","audience":"general"},{"title":"AI辅助开发的任务、上下文与验收","link":"/tools/ai/assisted-development-workflow","kind":"AI与Codex上手与对象","scope":"general","audience":"general"},{"title":"Codex Token 利用","link":"/tools/ai/practice/token-usage","kind":"AI与Codex完整实践与解答","scope":"historical","audience":"general"},{"title":"AI与Codex：完整实践与解答","link":"/tools/ai/practice/application","kind":"AI与Codex完整实践与解答","scope":"general","audience":"general"},{"title":"Codex 模型对比与选择","link":"/tools/ai/reference/model-selection","kind":"AI与Codex任务与配置","scope":"historical","audience":"general"}],"prev":false,"next":{"text":"Codex 模型对比与选择","link":"/tools/ai/reference/model-selection"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"Codex 模型对比与选择","link":"/tools/ai/reference/model-selection"}},"headers":[],"relativePath":"tools/ai/reference/plugin.md","filePath":"tools/ai/reference/plugin.md"}'),i={name:"tools/ai/reference/plugin.md"};function s(o,e,p,r,l,c){return t(),n("div",null,[...e[0]||(e[0]=[d('<h1 id="codex-插件用途与选择记录" tabindex="-1">Codex 插件用途与选择记录 <a class="header-anchor" href="#codex-插件用途与选择记录" aria-label="Permalink to &quot;Codex 插件用途与选择记录&quot;">​</a></h1><p><span id="codex-插件价值对比图"></span><span id="一、不使用任何插件"></span><span id="特点"></span><span id="二、仅使用-codex"></span><span id="特点-1"></span><span id="三、codex-superpowers"></span><span id="解决问题"></span><span id="四、codex-context7"></span><span id="解决问题-1"></span><span id="示例-gin-框架"></span><span id="五、codex-github"></span><span id="解决问题-2"></span><span id="六、codex-caveman"></span><span id="不使用-caveman"></span><span id="使用-caveman"></span><span id="效果"></span><span id="七、codex-episodic-memory"></span><span id="不使用"></span><span id="使用"></span><span id="八、推荐组合"></span><span id="普通开发者"></span><span id="go-后端"></span><span id="go-微服务"></span><span id="大型棋牌游戏项目"></span><span id="最终效果对比"></span><span id="一句话总结"></span></p><p>本文保留来源笔记中的插件分工，供理解不同扩展解决什么问题。插件名称、功能和可用性属于原记录，未在本次整理中重新验证。</p><h2 id="按任务选择能力" tabindex="-1">按任务选择能力 <a class="header-anchor" href="#按任务选择能力" aria-label="Permalink to &quot;按任务选择能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>原记录中的工具</th><th>关注的问题</th><th>使用时需要提供的上下文</th></tr></thead><tbody><tr><td>Codex 内置能力</td><td>读取项目、分析方案、编码与测试</td><td>明确需求、修改范围与验收命令</td></tr><tr><td>Superpowers</td><td>将需求梳理、方案、计划、审查组织成流程</td><td>项目约束、任务边界和完成标准</td></tr><tr><td>Context7</td><td>查询框架或库文档</td><td>实际依赖名称、版本与待确认 API</td></tr><tr><td>GitHub 集成</td><td>获取 PR、diff 与审查上下文</td><td>目标仓库、PR 与所需操作范围</td></tr><tr><td>Caveman</td><td>来源笔记中的摘要压缩方案</td><td>模块、接口和数据库的简短摘要</td></tr><tr><td>Episodic Memory</td><td>来源笔记中的跨任务记忆方案</td><td>需要保留的稳定决策和适用范围</td></tr></tbody></table><h2 id="组合与验证" tabindex="-1">组合与验证 <a class="header-anchor" href="#组合与验证" aria-label="Permalink to &quot;组合与验证&quot;">​</a></h2><p>先判断任务是否依赖外部文档、仓库服务或跨会话信息，再增加对应能力。Go 后端与微服务任务仍需明确需求、查看代码、运行测试和审查变更；安装插件本身不能保证避免 Bug、竞态或安全问题。</p><p>来源中的组合从文档查询逐步增加工作流、PR 和记忆能力。这里保留这条选择思路，不把插件数量当作项目质量或长任务成功率的指标。</p><p>具体任务模板见 <a href="/tools/ai/practice/assisted-development">AI 辅助开发实践</a>，上下文与工具开销见 <a href="/tools/ai/practice/token-usage">Codex Token 利用</a>。</p>',9)])])}const g=a(i,[["render",s]]);export{u as __pageData,g as default};
